typedef struct PH7_TzZoneRow PH7_TzZoneRow;
struct PH7_TzZoneRow
{
	const char *zName;   /* canonical identifier */
	sxu8 nName;
	sxu8 bBackward;      /* 1 = a compatibility LINK: out of ALL, in ALL_WITH_BC */
	char zCc[2];         /* its ISO 3166-1 country, or `??` for a zone with none */
	sxu32 iOfst;         /* where its TZif block starts in aTzPayload */
	sxu32 nByte;
	/* getLocation()'s other three fields, out of tzdata's `zone.tab`. A zone
	 * the tab does not list -- every backward link, `UTC`, the `Etc/` set --
	 * reads 0/0 with the literal comment `?`, which is what php answers for
	 * it and is NOT the empty comment a listed zone with no note carries. */
	double rLat;
	double rLong;
	const char *zComment;
	sxu16 nComment;
};
